// orchestrator/test/github-events.test.ts: the fingerprint rules, on saved logs from real red builds.
// Each case folder holds case.json ({ "lastGreenSha", "job" }), first.log and second.log: two red pushes, one cause.
import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { test } from "node:test";
import { fingerprint, firstError, normalize } from "../src/triggers/fingerprint.js";

const cases = new URL("./fixtures/red-builds/", import.meta.url);

for (const name of readdirSync(cases)) {
  test(`${name}: two red pushes with the same cause get the same ID`, () => {
    const read = (file: string) => readFileSync(new URL(`${name}/${file}`, cases), "utf8");
    const { lastGreenSha, job } = JSON.parse(read("case.json")) as { lastGreenSha: string; job: string };
    const id = (log: string) => fingerprint(lastGreenSha, [{ name: job, firstError: firstError(log) }]);
    assert.equal(id(read("first.log")), id(read("second.log")));
  });
}

test("normalize drops what changes between runs", () => {
  assert.equal(
    normalize("FAIL /tmp/ci-8sK2pq/fcp/frontend/src/a.test.tsx > shows a card 48ms"),
    normalize("FAIL /tmp/ci-Lx3qe9/fcp/frontend/src/a.test.tsx > shows a card 1.2s"),
  );
  assert.equal(normalize("at commit 4b7e2a91c0d3, line 42"), "at commit <hex>, line <n>");
});

test("firstError skips the exit-code line and passing tests", () => {
  const log = [
    "2026-10-13T10:02:11.1180032Z  ✓ src/ErrorBoundary/error.test.tsx (3 tests)",
    "2026-10-13T10:02:12.1257809Z src/api/projects.ts(12,7): error TS2339: Property 'emptyState' does not exist",
    "2026-10-13T10:02:13.1335586Z ##[error]Process completed with exit code 2.",
  ].join("\n");
  assert.equal(firstError(log), "src/api/projects.ts(12,7): error TS2339: Property 'emptyState' does not exist");
});

test("the job order does not change the ID", () => {
  const a = { name: "lint", firstError: "error x" };
  const b = { name: "test", firstError: "FAIL y" };
  assert.equal(fingerprint("9f2c4e1", [a, b]), fingerprint("9f2c4e1", [b, a]));
});
